程序1 %熵权值求权重
clc
clear
A=[58
38 14 8
57 10
50 45 11 9
52 12
42 47 8
12 50 15
45 42 12 15 46 16
47 44 13 10 49 13];
[m,n]=size(A);
h =max(A);%最大值
H=repmat(h,m,1);
Mij=A./H;%隶属度
A2=sum(Mij);
A22=repmat(A2,m,1);
Qij=Mij./A22;%归一化
Fj=-1/log(5)*Qij.*log(Qij);
fj=sum(Fj);%熵值
dj=1-fj;%差异系数
v=dj/sum(dj);%权重系数
B=Qij*v';%最终评价
disp(B)%显示结果
程序2 %车流密度k-车流速度v 关系图
clc
clear
syms t
x=[15 22 36 45 59 71 89 97 112]';
y=[65.0 66.0 53.0 51.5 50.0 40.5 32.0 25.5 10.0]';
f=fittype('a*t+b','independent','t','coefficients',{'a','b'});
cfun=fit(x,y,f)%显示拟合函数，系数
xi=0:1:120;
yi=cfun(xi);
plot(x,y,'r*',xi,yi,'b-');
set(gcf,'color',[1 1 1]);
grid on;
gtext('k=-0.53v+76.02');
title('车流密度k--车流速度v 关系图')
xlabel('车流速度km/h');
ylabel('车流密度pcu/km');
